/**
 * @name Path Traversal
 * @description Detects potential path traversal vulnerabilities where user input controls file paths.
 * @kind path-problem
 * @problem.severity error
 * @id py/path-traversal
 * @tags security
 *       external/cwe/cwe-022
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module PathTraversalConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    exists(DataFlow::CallCfgNode call |
      call = API::builtin("open").getACall() and
      sink = call.getArg(0)
    )
  }
}

module PathTraversalFlow = TaintTracking::Global<PathTraversalConfig>;
import PathTraversalFlow::PathGraph

from PathTraversalFlow::PathNode source, PathTraversalFlow::PathNode sink
where PathTraversalFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Path traversal from $@.", source.getNode(), "user input"

/**
 * @name Improper Input Validation in WebSocket Protocol
 * @description Processing WebSocket frames without proper validation can lead to protocol confusion or denial of service.
 * @kind path-problem
 * @problem.severity error
 * @id py/websocket-input-validation
 * @tags security
 *       external/cwe/cwe-020
 */

import python
import semmle.python.dataflow.new.DataFlow
import semmle.python.dataflow.new.TaintTracking
import semmle.python.dataflow.new.RemoteFlowSources
import semmle.python.ApiGraphs

module WebSocketInputValidationConfig implements DataFlow::ConfigSig {
  predicate isSource(DataFlow::Node source) {
    source instanceof RemoteFlowSource
  }

  predicate isSink(DataFlow::Node sink) {
    // Look for calls to websockets or wsproto send methods
    exists(DataFlow::CallCfgNode call |
      (
        call = API::moduleImport("websockets").getMember("send").getACall() or
        call = API::moduleImport("wsproto").getMember("send").getACall() or
        // Generic send on a transport/protocol object
        call.getFunction().asExpr().(Attribute).getAttr() = "send"
      ) and
      sink = call.getArg(0)
    )
  }
}

module WebSocketInputValidationFlow = TaintTracking::Global<WebSocketInputValidationConfig>;
import WebSocketInputValidationFlow::PathGraph

from WebSocketInputValidationFlow::PathNode source, WebSocketInputValidationFlow::PathNode sink
where WebSocketInputValidationFlow::flowPath(source, sink)
select sink.getNode(), source, sink, "Potential improper input validation in WebSocket communication from $@.", source.getNode(), "user input"
